def normalize_pair_text(s):
    u = (s or '').upper()
    replacements = {
        'STRUCTURAL': 'STR',
        'STRUCT': 'STR',
        'FIRE PROTECTION': 'FP',
        'FIRE_PROTECTION': 'FP',
        'SPRINKLER': 'FP',
        'MECHANICAL': 'MECH',
        'PLUMBING': 'PLUMB',
        '_VS_': '-',
        ' VS ': '-',
        '_': '-',
        ' ': '-',
    }
    for old, new in replacements.items():
        u = u.replace(old, new)
    return re.sub(r'-+', '-', u)

def infer_pair(test_name):
    upper = normalize_pair_text(test_name)
    for key in PAIR_KEYS:
        if key in upper:
            return key
    # handle reversed spelling from some tests
    for key in PAIR_KEYS:
        a, b = key.split('-')
        if f'{b}-{a}' in upper:
            return key
    return 'MISC'
```

